static void doubleAll(int[] values) {
    for (int i = 0; i < values.length; i++) {
        values[i] = values[i] * 2;
    }
}

int[] nums = {1, 2, 3};
doubleAll(nums);
System.out.println(Arrays.toString(nums));   // [2, 4, 6]
